const r = await tools.exec_command({cmd:"python3 - <<'PY'
from pypdf import PdfReader
import re
p='/app/paper.pdf'; reader=PdfReader(p)
print('PAGES',len(reader.pages))
terms=re.compile(r'decod|motion energy|dF/F|baseline corrected|10 consecutive|2 minute|two minute|behavio|arousal|526|33 %|P7|P14|20 minutes|30 Hz|tracked across',re.I)
for i,page in enumerate(reader.pages):
    txt=page.extract_text() or ''
    if terms.search(txt):
        print('\n'+'='*20,'PAGE',i+1,'='*20)
        lines=txt.splitlines()
        hits=[j for j,l in enumerate(lines) if terms.search(l)]
        keep=set()
        for j in hits:
            keep.update(range(max(0,j-4),min(len(lines),j+8)))
        last=-2
        for j in sorted(keep):
            if j>last+1: print('...')
            print(f'{j+1}: {lines[j]}')
            last=j
PY","workdir":"/app","yield_time_ms":30000,"max_output_tokens":50000});
